mapper.select:
SELECT
    scene_id AS sceneId,
    scene_name AS sceneName,
    algorithm_code AS algorithmCode
FROM sys_scene_config
WHERE delete_flag = 0
AND algorithm_code = #{algorithmCode}
AND tenant_id = #{tenantId}
AND industry_code = #{industryCode}

    AND app_ver_code = #{appVerCode}

SELECT
    rel.scene_id AS sceneId,
    rel.alarm_type AS alarmType,
    rel.alarm_type_name AS alarmTypeName
FROM sys_scene_alarm_rel rel
INNER JOIN sys_scene_config config ON rel.scene_id = config.scene_id
WHERE rel.delete_flag = 0
AND config.delete_flag = 0
AND config.algorithm_code = #{algorithmCode}
AND rel.tenant_id = #{tenantId}
AND rel.industry_code = #{industryCode}

    AND rel.app_ver_code = #{appVerCode}
